import React, { useState, useEffect } from 'react';
import './NotificationBell.css';

const NotificationBell = () => {
  const [notifications, setNotifications] = useState([]);
  const [showDropdown, setShowDropdown] = useState(false);

  useEffect(() => {
    // Mock notifications for now - in real app, fetch from /api/notifications
    setNotifications([
      { id: 1, title: 'New Session', message: 'Ocean Color 101 starts in 30 mins', is_read: false },
      { id: 2, title: 'Quiz Result', message: 'You scored 90% in Satellite Basics', is_read: true },
    ]);
  }, []);

  const unreadCount = notifications.filter(n => !n.is_read).length;

  return (
    <div className="notification-bell-container">
      <div className="bell-icon" onClick={() => setShowDropdown(!showDropdown)}>
        <span role="img" aria-label="bell">🔔</span>
        {unreadCount > 0 && <span className="notification-count">{unreadCount}</span>}
      </div>

      {showDropdown && (
        <div className="notification-dropdown">
          <h3>Notifications</h3>
          {notifications.length === 0 ? (
            <p className="no-notifications">No new notifications</p>
          ) : (
            <ul>
              {notifications.map(n => (
                <li key={n.id} className={n.is_read ? 'read' : 'unread'}>
                  <strong>{n.title}</strong>
                  <p>{n.message}</p>
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </div>
  );
};

export default NotificationBell;
